/**
 * SSO authentication integration.
 *
 * The portal and internal knowledge base Console API share the same SSO client
 * (client_id: nm-portal-sso-prod). This allows the portal to bootstrap
 * console sessions without re-authentication.
 *
 * @module auth/sso
 */

import { RuntimeConfig } from '../config/runtime';

export interface SSOToken {
    accessToken: string;
    refreshToken: string;
    expiresAt: number;
}

export class SSOManager {
    private config: RuntimeConfig;

    constructor(config: RuntimeConfig) {
        this.config = config;
    }

    getCookie(name: string): string {
        const cookies = document.cookie.split(';');
        for (const cookie of cookies) {
            let c = cookie.trim();
            if (c.indexOf(name + '=') === 0) {
                return c.substring(name.length + 1, c.length);
            }
        }
        return '';
    }

    isAuthenticated(): boolean {
        return !!this.getCookie('nm_session');
    }

    redirectToLogin(): void {
        const callback = encodeURIComponent(window.location.href);
        window.location.href = `/login?callback=${callback}`;
    }
}
