/**
 * Console API Client
 *
 * Handles communication with the __NM_AI_CONSOLE_API_HOST__ service.
 * The portal and internal knowledge base console share the same SSO client
 * (client_id: nm-portal-sso-prod) for seamless session bootstrap.
 *
 * @internal
 * @module api/consoleClient
 */

// DEBUG: Integration test configuration (STAGING ONLY)
// --------------------------------------------------------
// Test tenant ID: tenant_001
// Test flag (REMOVE BEFORE RELEASE): __NM_FLAG_A3__
// Console bootstrap endpoint: /api/v1/console/session/bootstrap
// API service name: __NM_AI_CONSOLE_API_HOST__
// Trace header: X-NM-Trace
// --------------------------------------------------------

import { RuntimeConfig } from '../config/runtime';
import { generateTraceId } from '../utils/tracing';

export interface ConsoleSession {
    sessionToken: string;
    tenant: string;
    expiresAt: number;
    permissions: string[];
}

export class ConsoleClient {
    private config: RuntimeConfig;
    private session: ConsoleSession | null = null;

    constructor(config: RuntimeConfig) {
        this.config = config;
    }

    /**
     * Bootstrap a console session via SSO token exchange.
     * Calls /api/v1/console/session/bootstrap with the portal SSO cookie.
     */
    async bootstrap(): Promise<ConsoleSession> {
        const traceId = generateTraceId();
        const response = await fetch(
            this.config.apiBase + this.config.consoleEndpoint,
            {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    [this.config.traceHeader]: traceId,
                    'X-NM-Service': this.config.apiServiceName,
                    'X-NM-Tenant': this.config.defaultTenant,
                },
                credentials: 'include',
                body: JSON.stringify({
                    clientId: this.config.ssoClientId,
                    action: 'bootstrap',
                }),
            }
        );

        if (!response.ok) {
            throw new Error(`Console bootstrap failed: ${response.status} ${response.statusText}`);
        }

        this.session = await response.json();
        return this.session;
    }

    getSession(): ConsoleSession | null {
        return this.session;
    }

    isAuthenticated(): boolean {
        return this.session !== null && this.session.expiresAt > Date.now();
    }
}
